string timeConversion(string s) {
    bool is_twelve = (s.substr(0, 2) == "12");
    bool is_pm = (s.substr(s.size() - 2) == "PM");

    if (is_pm) {
        if (is_twelve) {
            return s.substr(0, s.size() - 2);
        } else {
            int hour = stoi(s.substr(0, 2)) + 12;
            return to_string(hour) + s.substr(2, s.size() - 4);
        }
    } else {
        if (is_twelve) {
            return "00" + s.substr(2, s.size() - 4);
        } else {
            return s.substr(0, s.size() - 2);
        }
    }
}

int main() {
    string s;
    cin >> s;

    string result = timeConversion(s);
    cout << result << endl;

    return 0;
}

