using namespace std;

int getTotalX(const vector<int>& a, const vector<int>& b) {
    int res = 0;
    int maxA = *max_element(a.begin(), a.end());
    int minB = *min_element(b.begin(), b.end());

    for (int i = maxA; i <= minB; ++i) {
        bool isValid = true;

        for (int aa : a) {
            if (i % aa != 0) {
                isValid = false;
                break;
            }
        }

        if (isValid) {
            for (int bb : b) {
                if (bb % i != 0) {
                    isValid = false;
                    break;
                }
            }
        }

        if (isValid) {
            res++;
        }
    }

    return res;
}

int main() {
    int n, m;
    cin >> n >> m;

    vector<int> arr(n);
    for (int i = 0; i < n; ++i) {
        cin >> arr[i];
    }

    vector<int> brr(m);
    for (int i = 0; i < m; ++i) {
        cin >> brr[i];
    }

    int total = getTotalX(arr, brr);
    cout << total << endl;

    return 0;
}

