void plusMinus(const vector<int>& arr) {
    int n = arr.size();
    int p = 0, m = 0, z = 0;
    for (int x : arr) {
        if (x > 0) {
            p++;
        } else if (x < 0) {
            m++;
        } else {
            z++;
        }
    }
    cout << fixed << setprecision(6) << static_cast<double>(p) / n << endl;
    cout << fixed << setprecision(6) << static_cast<double>(m) / n << endl;
    cout << fixed << setprecision(6) << static_cast<double>(z) / n << endl;
}

