using namespace std;

string organizingContainers(const vector<vector<int>>& container) {
    int n = container.size();
    vector<int> ball_cnt(n, 0);
    unordered_map<int, int> cc;

    for (const auto& c : container) {
        int sum = accumulate(c.begin(), c.end(), 0);
        cc[sum]++;
        for (int i = 0; i < n; ++i) {
            ball_cnt[i] += c[i];
        }
    }

    for (const auto& bc : ball_cnt) {
        if (cc.find(bc) != cc.end() && cc[bc] > 0) {
            cc[bc]--;
        } else {
            return "Impossible";
        }
    }
    return "Possible";
}

int main() {
    int q;
    cin >> q;
    cin.ignore();

    for (int q_itr = 0; q_itr < q; ++q_itr) {
        int n;
        cin >> n;
        cin.ignore();

        vector<vector<int>> container(n, vector<int>(n));
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                cin >> container[i][j];
            }
        }

        string result = organizingContainers(container);
        cout << result << endl;
    }

    return 0;
}

