int getMoneySpent(vector<int>& keyboards, vector<int>& drives, int b) {
    sort(keyboards.begin(), keyboards.end());
    sort(drives.begin(), drives.end());
    int res = -1;
    for (int k : keyboards) {
        int x = -1;
        for (int d : drives) {
            if (k + d <= b) {
                x = k + d;
            } else {
                break;
            }
        }
        if (x == -1) {
            break;
        } else {
            res = max(res, x);
        }
    }
    return res;
}

int main() {
    int b, n, m;
    cin >> b >> n >> m;

    vector<int> keyboards(n);
    vector<int> drives(m);

    for (int i = 0; i < n; i++) {
        cin >> keyboards[i];
    }

    for (int i = 0; i < m; i++) {
        cin >> drives[i];
    }

    int moneySpent = getMoneySpent(keyboards, drives, b);
    cout << moneySpent << endl;

    return 0;
}

