string kangaroo(int x1, int v1, int x2, int v2) {
    if (x1 > x2) {
        swap(x1, x2);
        swap(v1, v2);
    }
    int dv = v1 - v2;
    bool res;
    if (dv <= 0) {
        res = (x1 == x2);
    } else {
        int dx = x2 - x1;
        res = (dx % dv == 0);
    }
    return res ? "YES" : "NO";
}

