int cost(const vector<int>& B) {
    int a = 0;
    int b = 0;
    int bi = B[0];
    for (size_t i = 1; i < B.size(); ++i) {
        int aa = max(a, b + bi - 1);
        int bb = max(b + abs(bi - B[i]), a + B[i] - 1);
        a = aa;
        b = bb;
        bi = B[i];
    }
    return max(a, b);
}

