    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> queries(q);
    for (int i = 0; i < q; ++i) {
        cin >> queries[i];
    }

    vector<int> result = circularArrayRotation(a, k, queries);

    for (int res : result) {
        cout << res << endl;
    }

    return 0;
}

