string appendAndDelete(string s, string t, int k) {
    int i = 0;
    while (i < min(s.length(), t.length()) && s[i] == t[i]) {
        i++;
    }
    int x = s.length() + t.length() - (2 * i);
    if (x <= k && ((k - x) % 2 == 0 || (s.length() + t.length()) <= k)) {
        return "Yes";
    } else {
        return "No";
    }
}

int main() {
    string s;
    string t;
    int k;

    cin >> s;
    cin >> t;
    cin >> k;

    string result = appendAndDelete(s, t, k);
    cout << result << endl;

    return 0;
}

