vector<int> climbingLeaderboard(vector<int> ranked, vector<int> player) {
    vector<int> res;
    vector<pair<int, int>> x;
    x.emplace_back(ranked[0], 1);

    for (size_t i = 1; i < ranked.size(); ++i) {
        if (ranked[i] != x.back().first) {
            x.emplace_back(ranked[i], x.back().second + 1);
        }
    }

    int i = x.size() - 1;
    for (int p : player) {
        while (i >= 0 && p > x[i].first) {
            i--;
        }
        if (i < 0) {
            res.push_back(1);
        } else if (p == x[i].first) {
            res.push_back(x[i].second);
        } else {
            res.push_back(x[i].second + 1);
        }
    }

    return res;
}

int main() {
    int ranked_count;
    cin >> ranked_count;
    vector<int> ranked(ranked_count);

    for (int i = 0; i < ranked_count; ++i) {
        cin >> ranked[i];
    }

    int player_count;
    cin >> player_count;
    vector<int> player(player_count);

    for (int i = 0; i < player_count; ++i) {
        cin >> player[i];
    }

    vector<int> result = climbingLeaderboard(ranked, player);

    for (size_t i = 0; i < result.size(); ++i) {
        cout << result[i];
        if (i < result.size() - 1) {
            cout << "\n";
        }
    }

    return 0;
}

