vector<int> permutationEquation(const vector<int>& p) {
    int n = p.size();
    vector<int> a(n + 1);
    for (int i = 0; i < n; ++i) {
        a[p[i]] = i + 1;
    }
    vector<int> result;
    for (int i = 1; i <= n; ++i) {
        result.push_back(a[a[i]]);
    }
    return result;
}

int main() {
    int n;
    cin >> n;

    vector<int> p(n);
    for (int i = 0; i < n; ++i) {
        cin >> p[i];
    }

    vector<int> result = permutationEquation(p);

    for (const int& res : result) {
        cout << res << endl;
    }

    return 0;
}

