// Complete the jumpingOnClouds function below.
int jumpingOnClouds(const vector<int>& c, int k) {
    int e = 100;
    int i = 0;
    while (true) {
        i = (i + k) % c.size();
        e -= 1 + (2 * c[i]);
        if (i == 0) {
            break;
        }
    }
    return e;
}

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> c(n);
    for (int i = 0; i < n; ++i) {
        cin >> c[i];
    }

    int result = jumpingOnClouds(c, k);
    cout << result << endl;

    return 0;
}

