vector<int> cutTheSticks(vector<int> arr) {
    map<int, int> d;
    for (int a : arr) {
        d[a]++;
    }

    vector<int> res;
    res.push_back(arr.size());

    int previousCount = arr.size();
    for (auto it = d.begin(); it != prev(d.end()); ++it) {
        previousCount -= it->second;
        res.push_back(previousCount);
    }

    return res;
}

int main() {
    int n;
    cin >> n;

    vector<int> arr(n);
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    vector<int> result = cutTheSticks(arr);

    for (size_t i = 0; i < result.size(); i++) {
        cout << result[i];
        if (i < result.size() - 1) {
            cout << '\n';
        }
    }

    return 0;
}

