vector<int> compareTriplets(const vector<int>& a, const vector<int>& b) {
    vector<int> res(2, 0);
    for (size_t i = 0; i < a.size(); ++i) {
        if (a[i] > b[i]) {
            res[0] += 1;
        } else if (b[i] > a[i]) {
            res[1] += 1;
        }
    }
    return res;
}

int main() {
    vector<int> a(3);
    vector<int> b(3);

    string input;

    getline(cin, input);
    stringstream ss_a(input);
    for (int i = 0; i < 3; ++i) {
        ss_a >> a[i];
    }

    getline(cin, input);
    stringstream ss_b(input);
    for (int i = 0; i < 3; ++i) {
        ss_b >> b[i];
    }

    vector<int> result = compareTriplets(a, b);

    cout << result[0] << " " << result[1] << endl;

    return 0;
}

